[{"role":"use","type":"use_controls_body"},{"role":"use_mutual","type":"body_generates_use"},{"role":"body_mutual","type":"use_controls_body"},{"role":"changed_use","type":"body_controls_use"}],"movingLine":{"fullText":"干父之蛊，小有悔，无大咎。","terms":[],"automaticPolarityScore":null,"applicationMustBeCurated":true,"label":"九三","sourceRef":{"sourceId":"user-yijing64","startChar":19288,"endChar":19401,"startLine":763,"endLine":767}},"referenceContext":{"castingDate":"2026-11-11","dayGanzhi":"己丑","monthOrder":"summer-fire","monthBranches":["巳","午"],"purpose":"explicit-qi-comparison-and-date-render-test;not-real-simultaneous-seasonal-casts"}},"decision":{"id":"career.interview.interview-pass/18/3/summer-fire/pass-after-correction","outcomeCode":"pass-after-correction","question_type":"interview_pass","questionScope":"one-interview-stage","method":"project-application-of-fame-chapter;not-a-verbatim-classical-interview-rule","sourceIds":["mh-056","mh-058","mh-071","mh-101","mh-116","mh-117","mh-119","mh-143","user-void-extension","user-void-timing"],"counterevidence":[{"fact":"本用及体互仍克体，盘中无直接生体者","resolution":"木休而土相可承接，金死耗较轻，末后土可制囚水，结合小悔无大咎取修正后有望通过；只给受阻期，不捏造通过日。"}],"lineApplication":{"evidence":["小有悔","无大咎"],"conditions":["承认可以修正，不把无大咎直接当成考察已经通过"],"allDetectedTerms":[]},"indirectEffectsApplied":[],"interpretationProvenance":"assistant-authored;not-observed-feedback;not-scientifically-verified-prediction"},"copy":{"title":"前面有难处，修正后仍有望通过","short":{"decisionId":"career.interview.interview-pass/18/3/summer-fire/pass-after-correction","text":"这轮面试有望在解释和修正后通过，开头不会特别顺。遇到不够匹配或没有说清的地方，及时补充，比一味坚持原来的回答更有用。中间仍会有追问，后段有处理余地；应期提示需要谨慎沟通的时段，先把这一轮的问题答实。"},"long":{"decisionId":"career.interview.interview-pass/18/3/summer-fire/pass-after-correction","opening":"起初有牵制，但仍有承接余地。艮土体夏令属相，巽木用属休而克体，考察要求会带来压力，体土自身却有一定力量，不至于完全难以应对。","process":"中段还需解释。体互震木属休，继续克体，问题可能反复出现；用互兑金属死，受体土所生，耗费相对较轻。把可以修正的地方说具体，进展才更容易接下去。","ending":"九三“小有悔，无大咎”，重点在发现问题后有所修正。变用坎水属囚，受相土体所克，末后的事情较有处理空间。前面的牵制仍在，但体有承接力、后段可调整，这轮取修正后有望通过。","summary":"本轮偏向有机会通过，宜先改正和补充，再跟进反馈。收到进一步追问时，把事实讲清，不急着争一个输赢。"}},"timingSlots":[{"id":"obstruction","kind":"control","role":"use","event":"本轮面试追问或补充沟通受阻","valence":"凶","ruleIds":["adverse-event"],"sourceIds":["mh-116","mh-143"],"prefix":"留意","suffix":"前后，追问或补充沟通较易受阻，属阶段性的凶应。把这些问题处理好，整轮仍有通过机会；这些日期并非结果公布日。","token":"{{date:obstruction}}","branches":["寅","卯"],"displayLimit":2,"method":"element-qi","scale":"day","emptyText":"本次可显示范围内暂无相应候选日期。"}],"baseProse":true,"coreVoidNotes":[],"voidReleaseSpecs":[],"voidTimingSlots":[],"voidTimingText":"","lineApplication":{"evidence":["小有悔","无大咎"],"conditions":["承认可以修正，不把无大咎直接当成考察已经通过"]},"counterevidence":[{"fact":"本用及体互仍克体，盘中无直接生体者","resolution":"木休而土相可承接，金死耗较轻，末后土可制囚水，结合小悔无大咎取修正后有望通过；只给受阻期，不捏造通过日。"}],"sourceIds":["mh-056","mh-058","mh-071","mh-101","mh-116","mh-117","mh-119","mh-143","user-void-extension","user-void-timing"],"review":{"status":"author-checked","actor":"assistant-author","version":"interview-pass-1.1.0","scope":"base-prose-and-recorded-void-profile;equivalent-qi-month-slots-share-written-text;exempt-core-void-does-not-change-verdict","verification":"computed-facts-plus-authored-judgment;not-independent-human-expert-certification","checks":{"chart-and-moving-line":{"status":"pass","evidence":[{"sourceId":"project-interview-authoring","locator":"18/3","reason":"Canonical six-line, mutual and one-line change recalculation"}]},"body-use-position":{"status":"pass","evidence":[{"sourceId":"project-interview-authoring","locator":"canonical-role-assignment","reason":"Original body is retained in all three stages"}]},"question-method-match":{"status":"pass","evidence":[{"sourceId":"project-interview-authoring","locator":"mh-071;project-interview-stage-application-v1","reason":"Fame chapter applied to this interview stage, separate from offer"}]},"relation-directions":{"status":"pass","evidence":[{"sourceId":"project-interview-authoring","locator":"facts.directRelations","reason":"Four direct relations independently recalculat