-verbatim-classical-interview-rule","sourceIds":["mh-056","mh-058","mh-071","mh-101","mh-116","mh-117","mh-119","mh-143","user-void-extension","user-void-timing"],"counterevidence":[{"fact":"爻有征凶，本用克体，末后泄体","resolution":"征凶的条件是偏经而强求，完整提示其警戒；体土相可承接休木牵制，两互相土比和、末金死耗轻，取守正后的通过机会。"}],"lineApplication":{"evidence":["颠颐","拂经","征凶"],"conditions":["不指认求职者实际撒谎；将爻意用于回答宜真实、避免勉强迎合的建议"],"allDetectedTerms":[{"term":"征凶","start":10,"end":12,"requiresContextualInterpretation":true}]},"indirectEffectsApplied":[],"interpretationProvenance":"assistant-authored;not-observed-feedback;not-scientifically-verified-prediction"},"copy":{"title":"有望通过，别为迎合要求勉强作答","short":{"decisionId":"career.interview.interview-pass/27/2/summer-fire/pass-if-grounded","text":"这轮面试有望通过，中间有继续沟通的基础。开头仍可能感到压力，回答时不必为了显得合适而把没做过的事情说满。把真实职责和做法讲具体，更有利于推进；应期提示追问或沟通较易受阻的时段，及时澄清后再跟进本轮结果。"},"long":{"decisionId":"career.interview.interview-pass/27/2/summer-fire/pass-if-grounded","opening":"起初有压力，但你这边仍有承接条件。艮土体夏令属相，震木用属休而克体，牵制相对有限。对不明确的要求，可以先问清再作答。","process":"中段有配合的基础。体互、用互坤土同属相，与体比和，能够缓和前面的不顺。沟通仍需继续，宜主动把不清楚的要求问明白。","ending":"六二“颠颐，拂经，于丘颐，征凶”，提醒勉强求取、偏离正道反而不利。变用兑金属死，虽受体土所生，耗费较轻。体有承接力、中段能配合，这轮取据实回答后有望通过。","summary":"本轮有望能过，回答应守住真实和具体。遇到追问及时澄清，后面再看明确反馈。"}},"timingSlots":[{"id":"obstruction","kind":"control","role":"use","event":"本轮面试追问或补充沟通受阻","valence":"凶","ruleIds":["adverse-event"],"sourceIds":["mh-116","mh-143"],"prefix":"留意","suffix":"前后，追问或补充沟通较易受阻，属阶段性的凶应。把这些问题处理好，整轮仍有通过机会；这些日期并非结果公布日。","token":"{{date:obstruction}}","branches":["寅","卯"],"displayLimit":2,"method":"element-qi","scale":"day","emptyText":"本次可显示范围内暂无相应候选日期。"}],"baseProse":true,"coreVoidNotes":[],"voidReleaseSpecs":[],"voidTimingSlots":[],"voidTimingText":"","lineApplication":{"evidence":["颠颐","拂经","征凶"],"conditions":["不指认求职者实际撒谎；将爻意用于回答宜真实、避免勉强迎合的建议"]},"counterevidence":[{"fact":"爻有征凶，本用克体，末后泄体","resolution":"征凶的条件是偏经而强求，完整提示其警戒；体土相可承接休木牵制，两互相土比和、末金死耗轻，取守正后的通过机会。"}],"sourceIds":["mh-056","mh-058","mh-071","mh-101","mh-116","mh-117","mh-119","mh-143","user-vo