，受体水所克，相关要求较实；用互坎水属囚，与体比和，协调仍有基础，但同弱水的推动有限。需要回应的部分，宜逐项答清。","ending":"六五“君子维有解，吉，有孚于小人”，有解开困难的积极方向。变用兑金属死而生体，帮助虽弱，仍有其作用。这轮取认真解开疑点后有望通过，进展偏慢，不宜只等一个好消息。","summary":"本轮仍有望能过，落实较费力。先把问答和补充要求完成，再依据实际反馈安排下一步。"}},"timingSlots":[{"id":"result","kind":"support","role":"changed_use","event":"本轮面试通过结果明朗","valence":"吉","ruleIds":["fame-date"],"sourceIds":["mh-071","mh-116","mh-143"],"prefix":"可留意","suffix":"，这是本轮面试较易得到积极反馈、通过结果较易明朗的有利窗口，属吉应。具体进度以招聘方通知为准。","token":"{{date:result}}","branches":["申","酉"],"displayLimit":2,"method":"element-qi","scale":"day","emptyText":"本次可显示范围内暂无相应候选日期。"}],"baseProse":true,"coreVoidNotes":[],"voidReleaseSpecs":[],"voidTimingSlots":[],"voidTimingText":"","lineApplication":{"evidence":["君子维有解","吉","有孚于小人"],"conditions":["不把小人直接指认为面试官或同事；取解开牵连的事项象意"]},"counterevidence":[{"fact":"体水囚、互水同囚、火旺待制、变金死助弱","resolution":"承认弱体和帮助有限；爻吉以解开牵连为实质条件，变用仍直接生体，取有望慢成而非确定通过。"}],"sourceIds":["mh-056","mh-058","mh-071","mh-101","mh-116","mh-117","mh-119","mh-143","user-void-extension","user-void-timing"],"review":{"status":"author-checked","actor":"assistant-author","version":"interview-pass-1.1.0","scope":"base-prose-and-recorded-void-profile;equivalent-qi-month-slots-share-written-text;exempt-core-void-does-not-change-verdict","verification":"computed-facts-plus-authored-judgment;not-independent-human-expert-certification","checks":{"chart-and-moving-line":{"status":"pass","evidence":[{"sourceId":"project-interview-authoring","locator":"40/5","reason":"Canonical six-line, mutual and one-line change recalculation"}]},"body-use-position":{"status":"pass","evidence":[{"sourceId":"project-interview-authoring","locator":"canonical-role-assignment","reason":"Original body is retained in all three stages"}]},"question-method-match":{"status":"pass","evidence":[{"sourceId":"project-interview-authoring","locator":"mh-071;project-interview-stage-application-v1","reason":"Fame chapter applied to this interview stage, separate from offer"}]},"relation-directions":{"status":"pass","