ater/pass-with-slow-progress","opening":"起初有可以接续的机会。兑金用属休而生坎水体，帮助不算强，但坎水得冬令而旺，能够承接这份支持，事情仍有向前的基础。","process":"中间可能需要多花精力解释。体互离火冬令属死，受体水所克，相关问题有处理余地；用互巽木属相，受体水所生，补充沟通也有耗费。推进虽慢，沟通的条件还在。","ending":"九四“来徐徐，困于金车，吝，有终”，同时留下了迟缓、为难与最后有终的意思。变用坎水与体比和，又同得冬令，后面的协调基础较好。结合本用生体，这轮偏向能通过，需要耐心把过程走完。","summary":"本轮倾向能过，但等待和补充沟通可能较多。继续跟进本轮要求，留意有利应期中的结果变化。"}},"timingSlots":[{"id":"result","kind":"support","role":"use","event":"本轮面试通过结果明朗","valence":"吉","ruleIds":["fame-date"],"sourceIds":["mh-071","mh-116","mh-143"],"prefix":"可重点留意","suffix":"，这是本轮面试通过结果较易明朗的有利窗口，属吉应。按实际通知继续跟进。","token":"{{date:result}}","branches":["申","酉"],"displayLimit":2,"method":"element-qi","scale":"day","emptyText":"本次可显示范围内暂无相应候选日期。"}],"baseProse":true,"coreVoidNotes":[],"voidReleaseSpecs":[],"voidTimingSlots":[],"voidTimingText":"","lineApplication":{"evidence":["来徐徐","吝","有终"],"conditions":["金车只作受困取象，不编造乘车迟到、交通事故或实际交通安排"]},"counterevidence":[{"fact":"用互受体生，兑金冬休，爻有吝与困","resolution":"承认迟缓费力；体水旺、末后同气得令、爻有终，保留有望通过。"}],"sourceIds":["mh-056","mh-058","mh-071","mh-101","mh-116","mh-117","mh-119","mh-143","user-void-extension","user-void-timing"],"review":{"status":"author-checked","actor":"assistant-author","version":"interview-pass-1.1.0","scope":"base-prose-and-recorded-void-profile;equivalent-qi-month-slots-share-written-text;exempt-core-void-does-not-change-verdict","verification":"computed-facts-plus-authored-judgment;not-independent-human-expert-certification","checks":{"chart-and-moving-line":{"status":"pass","evidence":[{"sourceId":"project-interview-authoring","locator":"47/4","reason":"Canonical six-line, mutual and one-line change recalculation"}]},"body-use-position":{"status":"pass","evidence":[{"sourceId":"project-interview-authoring","locator":"canonical-role-assignment","reason":"Original body is retained in all three stages"}]},"question-method-match":{"status":"pass","evidence":[{"sourceId":"project-interview-authoring","locator":"mh-071;project-interview-stage-application-v1","reason":"Fame chapter