-progress","opening":"起初有可以争取的支持。坎水体春令属休，兑金用属囚而生体，帮助较弱，尚不足以很快把结果定下来，仍要靠具体回答接住机会。","process":"中段较耗精力。体互离火属相，受体水所克，相关要求需要认真处理；用互巽木当旺，受体水所生，解释和补充的耗费较明显。宜按问题逐项说清，减少无关铺陈。","ending":"九四“来徐徐，困于金车，吝，有终”，把迟缓、为难和最后有终一起留下。变用坎水属休，与体比和，末后仍有协调基础。初期生体、末后比和，这轮取耐心推进后有望通过。","summary":"本轮倾向有机会通过，过程较慢。把补充要求完成，按实际进度跟进，不必急着催定结果。"}},"timingSlots":[{"id":"result","kind":"support","role":"use","event":"本轮面试通过结果明朗","valence":"吉","ruleIds":["fame-date"],"sourceIds":["mh-071","mh-116","mh-143"],"prefix":"可留意","suffix":"，这是本轮面试较易得到积极反馈、通过结果较易明朗的有利窗口，属吉应。具体进度以招聘方通知为准。","token":"{{date:result}}","branches":["申","酉"],"displayLimit":2,"method":"element-qi","scale":"day","emptyText":"本次可显示范围内暂无相应候选日期。"}],"baseProse":true,"coreVoidNotes":[],"voidReleaseSpecs":[],"voidTimingSlots":[],"voidTimingText":"","lineApplication":{"evidence":["来徐徐","吝","有终"],"conditions":["金车只作受困取象，不编造乘车迟到、交通事故或实际交通安排"]},"counterevidence":[{"fact":"金囚助弱、木旺泄体、火相待制，爻有吝与困","resolution":"保留迟缓费力；初用生体、末后比和与有终支持有望迟成，未把同休水写作旺助。"}],"sourceIds":["mh-056","mh-058","mh-071","mh-101","mh-116","mh-117","mh-119","mh-143","user-void-extension","user-void-timing"],"review":{"status":"author-checked","actor":"assistant-author","version":"interview-pass-1.1.0","scope":"base-prose-and-recorded-void-profile;equivalent-qi-month-slots-share-written-text;exempt-core-void-does-not-change-verdict","verification":"computed-facts-plus-authored-judgment;not-independent-human-expert-certification","checks":{"chart-and-moving-line":{"status":"pass","evidence":[{"sourceId":"project-interview-authoring","locator":"47/4","reason":"Canonical six-line, mutual and one-line change recalculation"}]},"body-use-position":{"status":"pass","evidence":[{"sourceId":"project-interview-authoring","locator":"canonical-role-assignment","reason":"Original body is retained in all three stages"}]},"question-method-match":{"status":"pass","evidence":[{"sourceId":"project-interview-authoring","locator":"mh-071;project-interview-stage-application-v1","reason":"Fame chapter applied